  (void)dpy;
  if (mask & GCForeground) gc->foreground = v->foreground;
  if (mask & GCLineWidth) gc->line_width = v->line_width;
  if (mask & GCCapStyle) gc->cap_style = v->cap_style;
  if (mask & GCJoinStyle) gc->join_style = v->join_style;
