import re
rows=[l for l in open('/Users/rod/build/stopwatch-screensaver/docs/porting-assessment.md') if l.startswith('| ') and re.match(r'\| [a-z0-9]+ \| (2d|gl)',l)]
hdr=[l for l in open('/Users/rod/build/stopwatch-screensaver/docs/porting-assessment.md') if 'Ported' in l and l.startswith('|')][:1]
print(hdr)
out={'only_pixmaps':[], 'pixmaps_plus_few':[]}
for l in rows:
    c=[x.strip() for x in l.strip().strip('|').split('|')]
    name,kind,band,speed,ported,_,gaps,flags=c[:8]
    if ported in ('✅','❌') or kind!='2d': continue
    if 'pixmaps' not in flags: continue
    ng=0 if gaps=='-' else len(gaps.split('`, `'))
    extra=[f for f in flags.split(', ') if f!='pixmaps']
    if ng==0 and not extra: out['only_pixmaps'].append(f"{name}({band})")
    elif ng<=3 and not extra: out['pixmaps_plus_few'].append(f"{name}({band},{ng}:{gaps[:60]})")
for k,v in out.items(): print(k,len(v)); print('  ',', '.join(v))

