  return 0;
}

int XDrawLines(Display *dpy, Drawable d, GC gc, XPoint *pts, int n, int mode) {
  (void)mode;
  if (gc->line_width > 1 && n > 0) {
    Canvas *c = xshim_target(dpy, d);
    if (!c) return 0;
    int stack_xy[2 * 64];
    int *xy = stack_xy;
    if (n > 64) {
      xy = (int *)malloc((size_t)n * 2 * sizeof(int));
      if (!xy) return 0;
    }
    for (int i = 0; i < n; i++) {
      xy[2 * i] = pts[i].x;
      xy[2 * i + 1] = pts[i].y;
    }
    stroke_polyline(c, gc, xy, n, 0);
    if (xy != stack_xy) free(xy);
    return 0;
  }
  for (int i = 1; i < n; i++)
    XDrawLine(dpy, d, gc, pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y);
  return 0;
}

