    xy = (int *)malloc((size_t)n * 2 * sizeof(int));
    if (!xy) return 0;
  }
  for (int i = 0; i < n; i++) {
    xy[2 * i] = pts[i].x;
    xy[2 * i + 1] = pts[i].y;
  }
  canvas_fill_polygon(dpy->canvas, xy, n, (uint16_t)gc->foreground);
  if (xy != stack_xy) free(xy);
  return 0;
}

